\begin{align*} n = \text{log}_2(m) \\ \text{where } m = 8 \text{ (number of inputs)} \\ n = \text{log}_2(8) = 3 \text{ select lines} \\ \text{Thus, } 3 \text{ select lines are required.} 
\text{Therefore, the answer is } 3. 
\text{Final result: } 3 \text{ select lines.} 
